on conflict (user_id, name) do update set muscle_group = excluded.muscle_group, recommended_sets = excluded.recommended_sets, status = excluded.status, tracking_mode = excluded.tracking_mode;

-- Do not impose the original PPL starter templates. Users create neutral saved routines instead.
update public.workout_templates set is_active = false
where name in ('Push', 'Legs', 'Pull') and split_day in ('Push', 'Legs', 'Pull');

create or replace function public.disable_default_split_templates()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.workout_templates set is_active = false
  where user_id = new.id and name in ('Push', 'Legs', 'Pull') and split_day in ('Push', 'Legs', 'Pull');
  return new;
end; $$;
create trigger on_auth_user_created_z_disable_default_split_templates
after insert on auth.users for each row execute procedure public.disable_default_split_templates();
